INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (18, 8, 'theory', 'Quiz: Queues and Workers');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 8, 0, 'What happens if a consumer finished the work and crashed before acknowledging?', '["The message disappears", "The message returns to the queue and is processed again", "The broker stops", "The message is deleted from the database"]', 1, 'Without an ack the broker returns the message: delivery is "at least once", so idempotency is needed.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 8, 1, 'What limits the number of parallel consumers in a group for a partitioned queue?', '["Message size", "The number of partitions", "The number of producers", "Disk size"]', 1, 'One partition is read by one consumer of the group; extra consumers sit idle.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 8, 2, 'What is a dead letter queue (DLQ) for?', '["Storing backups", "So poison messages do not block the others and can be examined by hand", "Speeding up delivery", "Encryption"]', 1, 'After a limited number of attempts the message goes to the DLQ; growth in its length is a reason for an alert.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 8, 3, 'Which metric best shows that there are not enough workers?', '["Producer CPU load", "Queue lag", "Message size", "The number of partitions"]', 1, 'Growing lag means messages arrive faster than they are processed.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 8, 4, 'How do you atomically tie a database write to sending a message?', '["Send first, then write", "The outbox pattern: the message is written to a table in the same transaction, and a separate process publishes it", "Send twice", "Use a single process"]', 1, 'Outbox rules out loss: the record and the intent are saved in one transaction.');
